/* Hardware Desk — browser client. Monetary and stock totals shown here are previews;
   the server performs the authoritative posting and returns saved documents. */
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => '₹' + Number(v || 0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const qty = v => Number(v || 0).toLocaleString('en-IN',{maximumFractionDigits:6});
const today = () => new Date().toLocaleDateString('en-CA');
const fmtDate = v => v ? new Date(v).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}) : '—';
const val = (o,...keys) => { for(const k of keys) if(o && o[k] != null) return o[k]; return 0; };
const store = {boot:null,view:'dashboard',category:'all',posMode:'all',favoriteIds:JSON.parse(localStorage.getItem('hd-favorites')||'[]'),recentSales:null,productSearch:'',cart:[],customerId:'',held:[],report:'sales',reportData:null,reportRange:'this_month',tablePage:0,tableSearch:'',sortHeader:'',sortDir:1,lineItems:[],modalKind:null};
const menu = [
  ['Overview',[['dashboard','Dashboard','▦']]],
  ['Operations',[['pos','POS / Billing','▣'],['inventory','Inventory','◫'],['products','Products','⬡'],['purchases','Purchases','↓'],['sales','Sales history','↗'],['customers','Customers','♧'],['suppliers','Suppliers','♙'],['credit','Credit / Udhaar','▤'],['quotations','Quotations','▧'],['expenses','Expenses','▥']]],
  ['Insights & settings',[['reports','Reports & analytics','▥'],['gst','GST reports','◇'],['users','Users & permissions','♟'],['settings','Settings','⚙']]]
];
const titleOf = id => menu.flatMap(g=>g[1]).find(x=>x[0]===id)?.[1] || id;
const isAdmin = () => String(store.boot?.user?.role || '').toLowerCase() === 'admin';
const isManager = () => ['admin','manager'].includes(String(store.boot?.user?.role || '').toLowerCase());
const minimumStock = p => Number(p.minimum_stock ?? p.min_stock ?? 0);
async function api(path, opts={}) {
  const headers = {'Accept':'application/json',...(opts.body ? {'Content-Type':'application/json'} : {}),...(opts.headers||{})};
  if(opts.method && opts.method.toUpperCase() !== 'GET' && store.boot?.csrf_token) headers['X-CSRF-Token']=store.boot.csrf_token;
  const res = await fetch(path,{credentials:'same-origin',...opts,headers});
  if(res.status === 401){location.href='/login';throw new Error('Session expired');}
  const type = res.headers.get('content-type') || '';
  const data = type.includes('json') ? await res.json() : await res.text();
  if(!res.ok){const error=new Error(typeof data === 'object' ? (data.error || data.detail || data.message || 'Request failed') : data || 'Request failed');error.status=res.status;throw error;}
  return data?.data ?? data;
}
const post = (url,body) => api(url,{method:'POST',body:JSON.stringify(body)});
const put = (url,body) => api(url,{method:'PUT',body:JSON.stringify(body)});
const patch = (url,body) => api(url,{method:'PATCH',body:JSON.stringify(body)});
function toast(message,type='success') { const t=document.createElement('div');t.className='toast '+type;t.textContent=message;$('#toast-stack').append(t);setTimeout(()=>t.remove(),4300); }
function fail(e){toast(e?.message || String(e),'error');}
const head = (title,subtitle='',actions='') => `<div class="page-head"><div><p class="eyebrow">${esc(titleOf(store.view).toUpperCase())}</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="head-actions">${actions}</div></div>`;
const empty = (title,detail='No records yet') => `<div class="empty"><span class="empty-icon">◫</span><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;
function showModal(title,body,footer='',wide=false){$('#modal').className='modal'+(wide?' wide':'');$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${footer || '<button class="btn" data-action="close-modal">Close</button>'}</div>`;$('#modal-backdrop').classList.remove('hidden');}
function closeModal(){ $('#modal-backdrop').classList.add('hidden');$('#modal').innerHTML='';store.modalKind=null;store.lineItems=[]; }
function formData(form){return Object.fromEntries(new FormData(form).entries());}
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><input id="f-${esc(name)}" name="${esc(name)}" type="${esc(type)}" value="${esc(value??'')}" ${extra}></div>`;}
function selectField(label,name,options,selected='',extra=''){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><select id="f-${esc(name)}" name="${esc(name)}" ${extra}>${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
const paymentTypeOptions=[['','Choose payment type'],['cash','Cash'],['upi','UPI'],['card','Debit / credit card'],['bank_transfer','Bank transfer'],['credit','Customer credit'],['split','Split payments']];
function splitPaymentFields(total){return `<div id="split-box" class="full hidden"><div class="split-line"><select id="split-method-1" aria-label="First payment method"><option value="cash">Cash</option><option value="upi">UPI</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option></select><input id="split-amount-1" aria-label="First payment amount" type="number" step="0.01" min="0.01" value="${total.toFixed(2)}" required><span></span></div><div class="split-line"><select id="split-method-2" aria-label="Second payment method"><option value="upi">UPI</option><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option></select><input id="split-amount-2" aria-label="Second payment amount" type="number" step="0.01" min="0.01" value="" required><span></span></div></div>`;}
function syncPaymentChoice(form,total){const method=form.elements.namedItem('method')?.value||'',amount=form.elements.namedItem('amount'),split=form.querySelector('#split-box'),submit=$('#modal [data-action="submit-sale"], #modal [data-action="submit-quote-convert"]');if(submit)submit.disabled=!method;if(amount){if(method==='credit'){amount.value='0';amount.disabled=true;}else if(method==='split'){amount.disabled=true;}else{if(amount.disabled)amount.value=Number(total||0).toFixed(2);amount.disabled=false;}amount.closest('.field')?.classList.toggle('hidden',method==='split');}if(split){split.classList.toggle('hidden',method!=='split');split.querySelectorAll('select,input').forEach(el=>{el.disabled=method!=='split';});}}
function listOptions(items,placeholder='Select',label='name'){return [['',placeholder],...items.map(x=>[x.id,x[label]||x.name||x.title||x.company_name])];}
function statusBadge(s){const t=String(s||'draft').toLowerCase();return `<span class="badge ${t.includes('cancel')||t.includes('overdue')?'danger':t.includes('paid')||t.includes('confirm')||t.includes('complete')?'':t.includes('partial')||t.includes('low')?'warning':'gray'}">${esc(s||'Draft')}</span>`;}
function renderNav(){const role=String(store.boot?.user?.role||'').toLowerCase();$('#nav').innerHTML=menu.map(([group,items])=>`<div class="nav-group-title">${group}</div>${items.filter(([id])=>!(role==='cashier'&&['dashboard','purchases','suppliers','expenses','reports','gst','users','settings','credit'].includes(id)) && !(role==='manager'&&['users','settings','gst'].includes(id))).map(([id,label,icon])=>`<button class="nav-item ${store.view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}`).join('');}
function setTop(){ $('#top-title').textContent=titleOf(store.view);$('#top-section').textContent=['dashboard','reports','gst'].includes(store.view)?'Overview':'Workspace';renderNav(); }
async function refreshBoot(){store.boot=await api('/api/bootstrap');store.held=rows(await api('/api/held-bills'));$('#sidebar-store').textContent=store.boot.settings?.store_name||store.boot.settings?.name||'Your store';$('#user-name').textContent=store.boot.user?.full_name||store.boot.user?.name||store.boot.user?.username||'User';$('#user-role').textContent=store.boot.user?.role||'';$('#avatar').textContent=($('#user-name').textContent[0]||'U').toUpperCase();renderNav();}
async function view(id){if(store.view!==id){store.tablePage=0;store.tableSearch='';store.sortHeader='';store.sortDir=1;}store.view=id;$('#sidebar').classList.remove('open');setTop();$('#content').innerHTML='<div class="loading">Loading…</div>';try{await ({dashboard:renderDashboard,pos:renderPos,inventory:renderInventory,products:renderProducts,purchases:renderPurchases,sales:renderSales,customers:renderCustomers,suppliers:renderSuppliers,credit:renderCredit,quotations:renderQuotations,expenses:renderExpenses,reports:renderReports,gst:renderGst,users:renderUsers,settings:renderSettings}[id]||renderDashboard)();}catch(e){$('#content').innerHTML=head(titleOf(id))+`<div class="card">${empty('Unable to load',e.message)}</div>`;fail(e);}}
function rangeDates(choice){const now=new Date(),d=new Date(now.getFullYear(),now.getMonth(),now.getDate());let a=new Date(d),b=new Date(d);if(choice==='yesterday'){a.setDate(a.getDate()-1);b=new Date(a);}else if(choice==='this_week'){a.setDate(a.getDate()-((a.getDay()+6)%7));}else if(choice==='this_month'){a.setDate(1);}else if(choice==='last_month'){a=new Date(d.getFullYear(),d.getMonth()-1,1);b=new Date(d.getFullYear(),d.getMonth(),0);}else if(choice==='this_fy'){a=new Date(d.getMonth()<3?d.getFullYear()-1:d.getFullYear(),3,1);}const f=x=>[x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-');return [f(a),f(b)];}
function dateFilter(choice=store.reportRange){return `<select id="date-range" aria-label="Date range"><option value="today" ${choice==='today'?'selected':''}>Today</option><option value="yesterday" ${choice==='yesterday'?'selected':''}>Yesterday</option><option value="this_week" ${choice==='this_week'?'selected':''}>This week</option><option value="this_month" ${choice==='this_month'?'selected':''}>This month</option><option value="last_month" ${choice==='last_month'?'selected':''}>Last month</option><option value="this_fy" ${choice==='this_fy'?'selected':''}>This financial year</option><option value="custom" ${choice==='custom'?'selected':''}>Custom range</option></select><span id="custom-range" class="${choice==='custom'?'':'hidden'}"><input type="date" id="range-start" value="${store.customStart||today()}"> to <input type="date" id="range-end" value="${store.customEnd||today()}"></span>`;}
function activeDates(){return store.reportRange==='custom'?[store.customStart||today(),store.customEnd||today()]:rangeDates(store.reportRange);}
function metric(label,value,foot='',cls=''){return `<div class="card metric ${cls}"><div class="label">${esc(label)}</div><div class="value">${value}</div><div class="foot">${esc(foot)}</div></div>`;}
function chartBars(series,compare=[]){const max=Math.max(1,...series.map(x=>Number(x.value||x.total||0)),...compare.map(x=>Number(x.value||x.total||0)));return `<div class="bars">${series.map((x,i)=>`<div class="bar-group"><div class="bar" title="${esc(x.label||x.date)}: ${money(x.value||x.total)}" style="height:${Math.max(2,100*Number(x.value||x.total||0)/max)}%"></div>${compare[i]?`<div class="bar secondary" title="${esc(compare[i].label||'Purchases')}: ${money(compare[i].value||compare[i].total)}" style="height:${Math.max(2,100*Number(compare[i].value||compare[i].total||0)/max)}%"></div>`:''}<span class="bar-label">${esc(String(x.label||x.date||'').slice(-5))}</span></div>`).join('')}</div>`;}
function chartCard(title,series,compare=[]){return `<div class="card card-pad chart-card"><div class="card-title"><h2>${esc(title)}</h2><span class="subtle">Last 12 months</span></div>${chartBars(series,compare)}<div class="chart-legend"><span><i></i> ${esc(title)}</span>${compare.length?'<span class="secondary"><i></i> Purchases</span>':''}</div></div>`;}
function rankCard(title,items,labelKey,valueKey,asMoney=false){const max=Math.max(1,...items.map(x=>Number(x[valueKey]||0)));return `<div class="card card-pad"><div class="card-title"><h2>${esc(title)}</h2><span class="subtle">Selected period</span></div>${items.length?items.slice(0,6).map((x,i)=>`<div class="rank-row"><span class="rank-num">${i+1}</span><div style="flex:1"><span class="rank-name">${esc(x[labelKey])}</span><div class="progress"><b style="width:${100*Number(x[valueKey]||0)/max}%"></b></div></div><span class="rank-qty">${asMoney?money(x[valueKey]):qty(x[valueKey])}</span></div>`).join(''):empty('No activity in this range')}</div>`;}
async function renderDashboard(){
  const [start,end]=activeDates(),d=await api(`/api/dashboard?start=${start}&end=${end}`),series=d.daily_sales||[],top=d.top_products||[];
  const cards=[metric('Sales',money(d.period_sales),'Selected period','dark'),metric('Purchases',money(d.period_purchases),'Selected period')];
  if(isAdmin())cards.push(metric('Gross profit',money(d.gross_profit),'After inventory cost','good'),metric('Net profit',money(d.net_profit),'After operating expenses','good'));
  cards.push(metric('Customer outstanding',money(d.customer_outstanding),'Receivables'),metric('Supplier outstanding',money(d.supplier_outstanding),'Payables'));
  if(isAdmin())cards.push(metric('Inventory at cost',money(d.inventory_cost_value),'Current stock'));
  cards.push(metric('Low stock items',qty(d.low_stock),'Needs attention',Number(d.low_stock)?'alert':''));
  const rank=top.length?top.slice(0,6).map((x,i)=>`<div class="rank-row"><span class="rank-num">${i+1}</span><div style="flex:1"><span class="rank-name">${esc(x.name)}</span><div class="progress"><b style="width:${100*Number(x.quantity||0)/Math.max(1,Number(top[0]?.quantity||1))}%"></b></div></div><span class="rank-qty">${qty(x.quantity)}</span></div>`).join(''):empty('No product activity','Complete a sale to see product rankings.');
  const monthlyRevenue=(d.monthly_revenue||[]).map(x=>({label:x.month,value:x.total}));
  const monthlyProfit=(d.monthly_profit||[]).map(x=>({label:x.month,value:x.net}));
  const salesPurchase=(d.sales_vs_purchases||[]).map(x=>({label:x.month,value:x.sales}));
  const purchases=(d.sales_vs_purchases||[]).map(x=>({label:x.month,value:x.purchases}));
  const expenses=(d.monthly_expenses||[]).map(x=>({label:x.month,value:x.total}));
  const extra=`<div class="dashboard-grid">${chartCard('Monthly revenue',monthlyRevenue)}${chartCard('Sales vs purchases',salesPurchase,purchases)}${isAdmin()?chartCard('Monthly net profit',monthlyProfit):''}${chartCard('Monthly expenses',expenses)}${rankCard('Best categories',d.category_performance||[],'category','revenue',true)}${rankCard('Payment methods',d.payment_breakdown||[],'method','total',true)}</div>`;
  $('#content').innerHTML=head('Business at a glance','Live totals from posted transactions.',`<button class="btn" data-view="reports">View reports</button><button class="btn primary" data-view="pos">＋ Start billing</button>`)+`<div class="filter-bar">${dateFilter()}</div><div class="metric-grid">${cards.join('')}</div><div class="dashboard-grid"><div class="card card-pad chart-card"><div class="card-title"><h2>Sales trend</h2><span class="subtle">Last 14 days</span></div>${chartBars(series)}<div class="chart-legend"><span><i></i> Sales</span></div></div><div class="card card-pad"><div class="card-title"><h2>Top-selling products</h2><span class="subtle">Selected period</span></div>${rank}</div></div><div class="tiny-grid">${metric('Products',qty(d.total_products),'Active catalog')}${metric('Stock units',qty(d.total_stock),'Across products')}${metric('GST collected',money(d.gst_collected),'Selected period')}</div>${extra}`;
}
function products(){return store.boot?.products||[];}
function productById(id){return products().find(p=>String(p.id)===String(id));}
function productCategory(p){return p.category_id||p.category?.id||'';}
const round2 = n => Math.round((Number(n)+Number.EPSILON)*100)/100;
function cartLineAmounts(row,p){const gross=round2(Number(row.quantity)*Number(row.unit_price)),discount=round2(gross*Number(row.discount_percent||0)/100),rate=store.boot?.settings?.is_gst_registered?Number(p.gst_rate||0):0,taxable=store.boot?.settings?.tax_inclusive?round2((gross-discount)/(1+rate/100)):gross-discount,gst=round2(taxable*rate/100);return {gross,discount,taxable,gst,total:round2(taxable+gst)};}
function cartLineTotal(row,p){return cartLineAmounts(row,p).total;}
function cartTotals(){let subtotal=0,discount=0,gst=0,total=0;for(const row of store.cart){const line=cartLineAmounts(row,productById(row.product_id)||{});subtotal+=line.gross;discount+=line.discount;gst+=line.gst;total+=line.total;}return {subtotal:round2(subtotal),discount:round2(discount),gst:round2(gst),total:round2(total)};}
function cartStorageKey(){return `hd-active-cart-${store.boot?.user?.id||'unknown'}`;}
function persistCart(){store.checkoutKey=null;store.preview=null;localStorage.setItem(cartStorageKey(),JSON.stringify({cart:store.cart,customerId:store.customerId}));}
function addToCart(id){const p=productById(id);if(!p)return;const stock=Number(p.current_stock||0);if(stock<=0&&!store.boot.settings?.allow_negative_stock){toast('This product is out of stock','error');return;}const existing=store.cart.find(r=>String(r.product_id)===String(id)&&r.unit===(p.unit||'pcs'));if(existing)existing.quantity=Number(existing.quantity)+1;else store.cart.push({product_id:p.id,quantity:1,unit:p.unit||'pcs',unit_price:Number(p.selling_price||0),discount_percent:0});persistCart();renderPos();}
function renderCart(){const t=cartTotals();return `<div class="card cart-panel"><div class="cart-header"><div><h2>Current bill</h2><small>${store.cart.length} item${store.cart.length===1?'':'s'}</small></div><button class="btn small" data-action="held-list">Held bills ${store.held.length?`(${store.held.length})`:''}</button></div><div class="cart-customer"><select id="pos-customer"><option value="">Walk-in customer</option>${(store.boot.customers||[]).map(c=>`<option value="${esc(c.id)}" ${String(store.customerId)===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="cart-items">${store.cart.length?store.cart.map((r,i)=>{const p=productById(r.product_id)||{};const line=cartLineTotal(r,p);return `<div class="cart-row"><div class="cart-row-head"><div><strong>${esc(p.name||'Product')}</strong><div class="sku">${esc(p.sku||'')} · GST ${esc(p.gst_rate||0)}%</div></div><div class="price">${money(line)}</div></div><div class="cart-controls"><div class="qty-control"><button data-action="cart-decrement" data-index="${i}" aria-label="Decrease">−</button><input type="number" min="0.001" step="0.000001" data-cart-field="quantity" data-index="${i}" value="${esc(r.quantity)}"><button data-action="cart-increment" data-index="${i}" aria-label="Increase">+</button></div><select class="unit-select" data-cart-field="unit" data-index="${i}">${[p.unit,...(p.conversions||[]).map(c=>c.symbol||c.unit)].filter((x,j,a)=>x&&a.indexOf(x)===j).map(u=>`<option ${u===r.unit?'selected':''}>${esc(u)}</option>`).join('')}</select>${isManager()?`<input class="tiny-input" type="number" min="0" step="0.01" data-cart-field="unit_price" data-index="${i}" value="${esc(r.unit_price)}" title="Selling rate">`:''}<input class="tiny-input" type="number" min="0" max="100" step="0.01" data-cart-field="discount_percent" data-index="${i}" value="${esc(r.discount_percent)}" title="Discount %"><button class="icon-button" data-action="cart-remove" data-index="${i}" title="Remove">×</button></div></div>`;}).join(''):empty('Your cart is empty','Click a product card to add it.')}</div><div class="cart-summary"><div class="sum-line"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><div class="sum-line"><span>Discount</span><strong>− ${money(t.discount)}</strong></div><div class="sum-line"><span>Estimated GST</span><strong>${money(t.gst)}</strong></div><div class="sum-line total"><span>Grand total</span><strong>${money(t.total)}</strong></div></div><div class="cart-actions"><button class="btn" data-action="clear-cart" ${store.cart.length?'':'disabled'}>Clear</button><button class="btn" data-action="hold-cart" ${store.cart.length?'':'disabled'}>Hold</button><button class="btn primary" data-action="pay-cart" ${store.cart.length?'':'disabled'}>Proceed to payment →</button></div></div>`;}
async function renderPos(){
  if(!store.boot?.products)await refreshBoot();
  if(!store.recentSales)store.recentSales=rows(await api('/api/sales'));
  const categories=store.boot.categories||[],search=store.productSearch.trim().toLowerCase(),frequency=new Map(),recent=[];
  for(const sale of store.recentSales){for(const item of sale.items||[]){const id=String(item.product_id);frequency.set(id,(frequency.get(id)||0)+Number(item.quantity||0));if(!recent.includes(id))recent.push(id);}}
  let shown=products().filter(p=>p.active!==false&&p.archived!==true&&(!search||[p.name,p.sku,p.barcode,p.brand].some(v=>String(v||'').toLowerCase().includes(search)))&&(store.category==='all'||String(productCategory(p))===String(store.category)));
  if(store.posMode==='favorites')shown=shown.filter(p=>store.favoriteIds.includes(String(p.id)));
  if(store.posMode==='recent')shown=shown.filter(p=>recent.includes(String(p.id))).sort((a,b)=>recent.indexOf(String(a.id))-recent.indexOf(String(b.id)));
  if(store.posMode==='frequent')shown=shown.filter(p=>frequency.has(String(p.id))).sort((a,b)=>frequency.get(String(b.id))-frequency.get(String(a.id)));
  const modes=[['all','All'],['frequent','Frequently sold'],['favorites','Favourites'],['recent','Recently sold']];
  const cards=shown.length?shown.map(p=>`<button class="product-card" data-action="add-cart" data-id="${esc(p.id)}" ${Number(p.current_stock||0)<=0&&!store.boot.settings?.allow_negative_stock?'disabled':''}><span class="product-symbol">${esc((p.name||'?').charAt(0).toUpperCase())}</span><span class="fav" data-action="toggle-favorite" data-id="${esc(p.id)}" title="Favourite">${store.favoriteIds.includes(String(p.id))?'★':'☆'}</span><strong>${esc(p.name)}</strong><span class="code">${esc(p.sku||'')}</span><span class="product-bottom"><span class="price">${money(p.selling_price)}</span><span class="stock ${Number(p.current_stock)<=minimumStock(p)?'low':''}">${qty(p.current_stock)} ${esc(p.unit||'')}</span></span></button>`).join(''):empty('No matching products','Try another search, category or view.');
  $('#content').innerHTML=head('Point of sale','Select products, review the bill and take payment.',`<button class="btn" data-action="new-customer-pos">＋ Customer</button><button class="btn" data-view="sales">Sales history</button>`)+`<div class="pos-layout"><section class="card pos-products"><div class="pos-toolbar"><div class="search-wrap"><input id="pos-search" type="text" placeholder="Search products, SKU or brand…" value="${esc(store.productSearch)}" autocomplete="off"></div></div><div class="category-scroll"><button class="category-pill ${store.category==='all'?'active':''}" data-category="all">All products</button>${categories.map(c=>`<button class="category-pill ${String(store.category)===String(c.id)?'active':''}" data-category="${esc(c.id)}">${esc(c.name)}</button>`).join('')}</div><div class="category-scroll" style="margin-top:-8px">${modes.map(([id,label])=>`<button class="category-pill ${store.posMode===id?'active':''}" data-pos-mode="${id}">${label}</button>`).join('')}</div><div class="product-grid">${cards}</div></section>${renderCart()}</div>`;
}
async function openPayment(){
  const cust=store.boot.customers?.find(c=>String(c.id)===String(store.customerId));
  const place=cust?.state_code||store.boot.settings?.state_code||'';
  const preview=await post('/api/sales/preview',{customer_id:store.customerId||null,place_of_supply_state:place,items:store.cart});
  store.preview=preview;
  store.checkoutKey ||= crypto.randomUUID();
  localStorage.setItem(cartStorageKey(),JSON.stringify({cart:store.cart,customerId:store.customerId,checkoutKey:store.checkoutKey}));
  const total=Number(preview.grand_total||0),isGst=Boolean(store.boot.settings?.is_gst_registered);
  showModal('Complete sale',`<div class="info-banner">${store.cart.length} items · Invoice total <strong>${money(total)}</strong> · GST ${money(preview.gst_total||0)}. This total is calculated by the server.</div><form id="payment-form" class="form-grid">${selectField('Invoice type','invoice_type',isGst?[['tax_invoice','GST tax invoice'],['bill_of_supply','Bill of supply'],['retail','Retail bill']]:[['retail','Retail bill']],'tax_invoice')}${selectField('Payment type','method',paymentTypeOptions.filter(([value])=>total>0||value!=='split'),'','required')}${field('Amount received','amount','number',total.toFixed(2),'min="'+(total>0?'0.01':'0')+'" step="0.01" required')}${field('Place of supply state code','place_of_supply_state','text',place,'maxlength="2" required')}${field('Reference / notes','notes','text','','class="full"')}${splitPaymentFields(total)}</form>`,`<button class="btn" data-action="close-modal">Back to bill</button><button class="btn primary" data-action="submit-sale" disabled>Generate invoice</button>`);
  syncPaymentChoice($('#payment-form'),total);
}
async function checkout(){
  const f=$('#payment-form');if(!f||!f.reportValidity())return;
  const data=formData(f),method=data.method,total=Number(store.preview?.grand_total||cartTotals().total);
  if(!method)throw new Error('Choose a payment type before generating the invoice.');
  let payments=[];
  if(method==='split'){
    payments=[{method:$('#split-method-1').value,amount:Number($('#split-amount-1').value)},{method:$('#split-method-2').value,amount:Number($('#split-amount-2').value)}];
    if(payments.some(x=>!Number.isFinite(x.amount)||x.amount<=0))throw new Error('Enter a positive amount for each split payment.');
    if(payments[0].method===payments[1].method)throw new Error('Choose two different methods for split payments.');
  }else if(method!=='credit'){
    const amount=Number(data.amount);
    if(!Number.isFinite(amount)||amount<0||(total>0&&amount<=0))throw new Error('Enter a positive amount received.');
    if(amount>0)payments=[{method,amount}];
  }
  if(method==='credit'&&!store.customerId)throw new Error('Select a customer for a credit sale.');
  const payload={customer_id:store.customerId||null,items:store.cart.map(r=>({...r,quantity:Number(r.quantity),unit_price:Number(r.unit_price),discount_percent:Number(r.discount_percent||0)})),payment_type:method,payments,invoice_type:data.invoice_type,place_of_supply_state:data.place_of_supply_state,notes:data.notes,idempotency_key:store.checkoutKey};
  const result=await post('/api/sales/checkout',payload);
  store.cart=[];store.customerId='';store.checkoutKey=null;store.preview=null;store.recentSales=null;persistCart();closeModal();await refreshBoot();await renderPos();
  const id=result.id||result.sale_id;
  showModal('Sale completed',`<div class="info-banner">Invoice <strong>${esc(result.invoice_no||result.invoice_number||id)}</strong> was saved successfully. Stock and payment records are updated.</div><div class="summary-strip"><div class="mini"><span>Invoice total</span><strong>${money(result.grand_total||result.total||total)}</strong></div><div class="mini"><span>Balance due</span><strong>${money(result.balance_due)}</strong></div></div>`,`<button class="btn" data-action="close-modal">Done</button><a class="btn" href="/invoices/${esc(id)}/print" target="_blank" rel="noopener">Print</a><a class="btn primary" href="/invoices/${esc(id)}/pdf" target="_blank" rel="noopener">Download PDF</a>`);
}
