  const actions=isManager()?`<button class="btn" data-action="import-products">Import CSV</button><a class="btn" href="/api/products/export?format=xlsx">Export Excel</a><button class="btn" data-action="new-category">＋ Category</button><button class="btn" data-action="new-unit">＋ Unit</button><button class="btn primary" data-action="new-product">＋ Add product</button>`:'';
  const body=shown.map(p=>`<tr><td class="strong">${esc(p.name)}</td><td>${esc(p.sku||'—')}</td><td>${esc(p.category_name||'—')}</td>${isManager()?`<td>${money(p.purchase_price)}</td>`:''}<td>${money(p.selling_price)}</td><td>${esc(p.gst_rate||0)}%</td><td>${qty(p.current_stock)} ${esc(p.unit||'')}</td>${isManager()?`<td><div class="table-actions"><button class="btn small" data-action="edit-product" data-id="${esc(p.id)}">Edit</button><button class="btn small" data-action="adjust-product" data-id="${esc(p.id)}">Adjust</button><button class="btn small" data-action="product-units" data-id="${esc(p.id)}">Units</button><button class="btn small" data-action="price-history" data-id="${esc(p.id)}">Prices</button><button class="btn small" data-action="attachments" data-kind="product" data-id="${esc(p.id)}">Image</button><button class="btn small danger" data-action="archive-product" data-id="${esc(p.id)}">Archive</button></div></td>`:''}</tr>`);
