async function renderInventory(){
  const data=rows(await api('/api/products'));store.boot.products=data;
  const low=data.filter(p=>Number(p.current_stock||0)<=minimumStock(p)),{shown,count}=pageRows(data);
  const actions=`<button class="btn" data-action="view-movements">Stock movements</button>${isManager()?`<button class="btn" data-action="reorder-list">Reorder suggestions</button><button class="btn primary" data-action="adjust-product-picker">＋ Stock adjustment</button>`:''}`;
  const metrics=`<div class="summary-strip"><div class="mini"><span>Products</span><strong>${data.length}</strong></div><div class="mini"><span>Low stock</span><strong>${low.length}</strong></div>${isManager()?`<div class="mini"><span>At purchase cost</span><strong>${money(data.reduce((n,p)=>n+Number(p.current_stock||0)*Number(p.weighted_avg_cost||p.purchase_price||0),0))}</strong></div>`:''}</div>`;
  const body=shown.map(p=>`<tr><td class="strong">${esc(p.name)}</td><td>${esc(p.sku||'—')}</td><td>${qty(p.current_stock)} ${esc(p.unit||'')}</td><td>${qty(minimumStock(p))}</td><td>${Number(p.current_stock||0)<=0?'<span class="badge danger">Out of stock</span>':Number(p.current_stock)<=minimumStock(p)?'<span class="badge warning">Low stock</span>':'<span class="badge">In stock</span>'}</td><td>${esc(p.rack_location||'—')}</td>${isManager()?`<td><button class="btn small" data-action="adjust-product" data-id="${esc(p.id)}">Adjust</button></td>`:''}</tr>`);
  $('#content').innerHTML=head('Inventory','Stock quantities reflect confirmed movements.',actions)+metrics+`<div class="filter-bar">${searchBar('Search inventory…')}</div>`+table(['Product','SKU','Available','Minimum','Status','Rack',...(isManager()?['Action']:[])],body,'No inventory yet',count);
}
