function documentLineRows(){return store.lineItems.length?store.lineItems.map((line,i)=>`<div class="line-item"><strong>${esc(productById(line.product_id)?.name||'Product')}</strong><span>${qty(line.quantity)} ${esc(line.unit)}</span><span>${money(line.purchase_price??line.unit_price)}</span><span>${esc(line.discount_percent||0)}% off</span><button class="icon-button" data-action="remove-document-line" data-index="${i}" title="Remove">×</button></div>`).join('')+`<div class="inline-total">Estimated subtotal ${money(store.lineItems.reduce((n,x)=>n+Number(x.quantity)*Number(x.purchase_price??x.unit_price)*(1-Number(x.discount_percent||0)/100),0))}</div>`:'<p class="muted" style="font-size:11px;margin:12px 0 0">No products added.</p>';}
function addDocumentLine(){const id=$('#f-line_product_id')?.value,p=productById(id),quantity=Number($('#f-line_quantity')?.value||0),price=Number($('#f-line_price')?.value||0),discount=Number($('#f-line_discount')?.value||0);if(!p||quantity<=0||price<0||discount<0||discount>100)throw new Error('Choose a product and enter a valid quantity, rate and discount.');const key=store.modalKind==='purchase'?'purchase_price':'unit_price';store.lineItems.push({product_id:p.id,quantity,unit:p.unit||'pcs',unit_id:p.base_unit_id,[key]:price,discount_percent:discount,gst_rate:Number(p.gst_rate||0)});$('#document-lines').innerHTML=documentLineRows();$('#f-line_quantity').value='1';$('#f-line_discount').value='0';}
function purchaseForm(kind='purchase'){store.lineItems=[];store.modalKind=kind;const isPo=kind==='purchase-order';showModal(isPo?'New purchase order':'Record purchase',`<form id="document-form" class="form-grid">${selectField('Supplier','supplier_id',listOptions(store.boot.suppliers||[],'Select supplier'),'','required')}${isPo?field('Expected date','expected_date','date',today()):field('Supplier invoice number','supplier_invoice_no','text','','required')}${field(isPo?'Order date':'Purchase date',isPo?'order_date':'purchase_date','date',today(),'required')}${field('Notes','notes','text','')}</form>${documentLineBuilder(kind)}`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-document">${isPo?'Create purchase order':'Save purchase draft'}</button>`,true);}
