  showModal((person?.name||'Account')+' · ledger',`<div class="summary-strip"><div class="mini"><span>Opening balance</span><strong>${money(person?.opening_balance)}</strong></div><div class="mini"><span>Outstanding balance</span><strong>${money(person?.outstanding_balance)}</strong></div></div>${entries.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Type</th><th>Source</th><th>Change</th><th>Balance</th></tr></thead><tbody>${body}</tbody></table></div>`:empty('No ledger entries')}`,`<button class="btn" data-action="close-modal">Close</button><a class="btn primary" href="/api/${route}/${esc(id)}/statement?format=pdf" target="_blank" rel="noopener">Statement PDF</a>`,true);
