async function renderCredit(){
  const [customerData,supplierData,customerReport,supplierReport]=await Promise.all([api('/api/customers'),api('/api/suppliers'),api(`/api/reports/customer_outstanding?end=${today()}`),api(`/api/reports/supplier_outstanding?end=${today()}`)]);
  const customers=rows(customerData),suppliers=rows(supplierData);store.boot.customers=customers;store.boot.suppliers=suppliers;
  const dueCustomers=customers.filter(x=>Number(x.outstanding_balance||0)>0),dueSuppliers=suppliers.filter(x=>Number(x.outstanding_balance||0)>0);
  const cards=[metric('Customer receivables',money(customerReport.summary?.total_outstanding),'Across '+dueCustomers.length+' customers','good'),metric('Supplier payables',money(supplierReport.summary?.total_outstanding),'Across '+dueSuppliers.length+' suppliers'),metric('Overdue customers',money(customerReport.summary?.total_overdue),'Past credit terms','alert'),metric('Overdue suppliers',money(supplierReport.summary?.total_overdue),'Past credit terms','alert')];
  const customerRows=dueCustomers.map(x=>`<tr><td class="strong">${esc(x.name)}</td><td>${money(x.outstanding_balance)}</td><td><button class="btn small" data-action="contact-payment" data-kind="customer" data-id="${esc(x.id)}">Receive</button></td></tr>`).join('');
  const supplierRows=dueSuppliers.map(x=>`<tr><td class="strong">${esc(x.name)}</td><td>${money(x.outstanding_balance)}</td><td><button class="btn small" data-action="contact-payment" data-kind="supplier" data-id="${esc(x.id)}">Pay</button></td></tr>`).join('');
  $('#content').innerHTML=head('Credit / Udhaar','Receivables, payables and overdue balances from posted ledger entries.',`<button class="btn" data-view="customers">Customer accounts</button><button class="btn" data-view="suppliers">Supplier accounts</button>`)+`<div class="metric-grid">${cards.join('')}</div><div class="two-col"><div class="card"><div class="card-pad card-title"><h2>Customer dues</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Balance</th><th></th></tr></thead><tbody>${customerRows}</tbody></table>${!dueCustomers.length?empty('No customer dues'):''}</div></div><div class="card"><div class="card-pad card-title"><h2>Supplier dues</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Supplier</th><th>Balance</th><th></th></tr></thead><tbody>${supplierRows}</tbody></table>${!dueSuppliers.length?empty('No supplier dues'):''}</div></div></div>`;
}
