async function saveQuotation(){const f=$('#document-form');if(!f.reportValidity())return;if(!store.lineItems.length)throw new Error('Add at least one product.');const body={...formData(f),items:store.lineItems};if(store.editQuoteId)await patch(`/api/quotations/${store.editQuoteId}`,body);else await post('/api/quotations',body);closeModal();store.editQuoteId=null;await view('quotations');toast('Quotation saved');}
async function openQuoteConvert(id){
  const quotes=rows(await api('/api/quotations')),quote=quotes.find(q=>String(q.id)===String(id));if(!quote)throw new Error('Quotation not found');
  if(quote.status!=='approved')throw new Error('A manager must approve this quotation before conversion.');
  const customer=(store.boot.customers||[]).find(c=>String(c.id)===String(quote.customer_id)),place=customer?.state_code||store.boot.settings?.state_code||'';
  const items=(quote.items||[]).map(i=>({product_id:i.product_id,unit_id:i.unit_id,quantity:Number(i.quantity),unit_price:Number(i.unit_price),discount_percent:i.discount_percent!=null?Number(i.discount_percent):(Number(i.quantity)&&Number(i.unit_price)?Number(i.discount)*100/(Number(i.quantity)*Number(i.unit_price)):0)}));
  const preview=await post('/api/sales/preview',{quotation_id:id,customer_id:quote.customer_id,place_of_supply_state:place,items});
  const total=Number(preview.grand_total||0),isGst=Boolean(store.boot.settings?.is_gst_registered);store.quoteTotal=total;
  showModal('Convert quotation · '+quote.number,`<div class="info-banner">Customer: <strong>${esc(quote.customer_name)}</strong> · Invoice total: <strong>${money(total)}</strong>. Stock will be deducted once when the sale is posted.</div><form id="quote-convert-form" class="form-grid">${selectField('Invoice type','invoice_type',isGst?[['tax_invoice','GST tax invoice'],['retail','Retail bill']]:[['retail','Retail bill']],isGst?'tax_invoice':'retail')}${selectField('Payment type','method',paymentTypeOptions.filter(([value])=>total>0||value!=='split'),'','required')}${field('Amount received','amount','number',total.toFixed(2),'min="'+(total>0?'0.01':'0')+'" max="'+total.toFixed(2)+'" step="0.01" required')}${field('Place of supply state code','place_of_supply_state','text',place,'maxlength="2" required')}${splitPaymentFields(total)}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-quote-convert" data-id="${esc(id)}" disabled>Generate invoice</button>`);
  syncPaymentChoice($('#quote-convert-form'),total);
}
async function submitQuoteConvert(id){
  const f=$('#quote-convert-form');if(!f||!f.reportValidity())return;
  const d=formData(f),method=d.method,total=Number(store.quoteTotal||0);
  if(!method)throw new Error('Choose a payment type before generating the invoice.');
  let payments=[];
  if(method==='split'){
    payments=[{method:$('#split-method-1').value,amount:Number($('#split-amount-1').value)},{method:$('#split-method-2').value,amount:Number($('#split-amount-2').value)}];
    if(payments.some(x=>!Number.isFinite(x.amount)||x.amount<=0))throw new Error('Enter a positive amount for each split payment.');
    if(payments[0].method===payments[1].method)throw new Error('Choose two different methods for split payments.');
  }else if(method!=='credit'){
    const amount=Number(d.amount);
    if(!Number.isFinite(amount)||amount<0||(total>0&&amount<=0))throw new Error('Enter a positive amount received.');
    if(amount>0)payments=[{method,amount}];
  }
  const result=await post(`/api/quotations/${id}/convert`,{payment_type:method,payments,invoice_type:d.invoice_type,place_of_supply_state:d.place_of_supply_state,idempotency_key:crypto.randomUUID()});
  closeModal();store.recentSales=null;await refreshBoot();await view('quotations');
  showModal('Quotation converted',`<div class="info-banner">Invoice <strong>${esc(result.invoice_no||result.id)}</strong> was posted. Balance due: ${money(result.balance_due||result.outstanding)}.</div>`,`<button class="btn" data-action="close-modal">Done</button><a class="btn" href="/invoices/${esc(result.id)}/print" target="_blank" rel="noopener">Print</a><a class="btn primary" href="/invoices/${esc(result.id)}/pdf" target="_blank" rel="noopener">PDF</a>`);
}
async function renderExpenses(){const data=rows(await api('/api/expenses'));const {shown,count}=pageRows(data),total=data.reduce((n,x)=>n+Number(x.amount||0),0);const body=shown.map(x=>`<tr><td>${fmtDate(x.expense_date)}</td><td class="strong">${esc(x.category)}</td><td>${esc(x.description||'—')}</td><td>${esc(x.payment_method||'—')}</td><td>${money(x.amount)}</td><td><button class="btn small" data-action="attachments" data-kind="expense" data-id="${esc(x.id)}">Receipt</button></td></tr>`);$('#content').innerHTML=head('Expenses','Operating expenses are tracked separately from inventory purchases.',`<button class="btn primary" data-action="new-expense">＋ Add expense</button>`)+`<div class="summary-strip"><div class="mini"><span>Recorded expenses</span><strong>${money(total)}</strong></div></div><div class="filter-bar">${searchBar('Search category or description…')}</div>`+table(['Date','Category','Description','Method','Amount','File'],body,'No expenses yet',count);}
