const businessReports=[['sales','Sales and returns'],['sales_daily','Daily sales'],['sales_weekly','Weekly sales'],['sales_monthly','Monthly sales'],['sales_yearly','Yearly sales'],['product_sales','Product sales'],['category_sales','Category sales'],['customer_sales','Customer sales'],['purchases','Purchases and returns'],['supplier_purchases','Supplier purchases'],['purchase_price_trends','Purchase price trends'],['inventory','Inventory valuation'],['stock_movement','Stock movement'],['stock_ageing','Stock ageing'],['profit','Gross and net profit'],['expenses','Expenses'],['customer_outstanding','Customer outstanding'],['supplier_outstanding','Supplier outstanding']];
