function reportGrid(data){if(data?.headers&&Array.isArray(data.rows)){const summary=data.summary||{};return `<div class="summary-strip">${Object.entries(summary).map(([k,v])=>`<div class="mini"><span>${esc(k.replaceAll('_',' '))}</span><strong>${/amount|total|tax|gst|profit|value|sales|purchase|expense|balance|cost|revenue|paid/i.test(k)?money(v):esc(v)}</strong></div>`).join('')}</div>${data.rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${data.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${data.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No data for this period')}`;}if(Array.isArray(data)){if(!data.length)return empty('No data for this period');const headers=Object.keys(data[0]||{});return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${esc(h.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${data.map(row=>`<tr>${headers.map(k=>`<td>${esc(row[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}return empty('No report data');}
async function renderReportPage(gst=false){const options=gst?gstReports:(isAdmin()?businessReports:businessReports.filter(x=>!['profit','purchase_price_trends'].includes(x[0])));if(!options.some(x=>x[0]===store.report))store.report=options[0][0];const [start,end]=activeDates(),url=`/api/reports/${store.report}?start=${start}&end=${end}`;const data=await api(url);store.reportData=data;$('#content').innerHTML=head(gst?'GST preparation reports':'Reports & analytics',gst?'Review taxable transactions and tax components before filing.':'Analyze transactions, stock and profitability from the database.',`<a class="btn" href="${url}&format=xlsx">Export Excel</a><a class="btn" href="${url}&format=pdf" target="_blank" rel="noopener">Export PDF</a>`)+`<div class="filter-bar">${dateFilter()}</div><div class="report-picker">${options.map(([id,label])=>`<button class="report-chip ${store.report===id?'active':''}" data-report="${id}">${esc(label)}</button>`).join('')}</div><div class="card card-pad"><div class="card-title"><h2>${esc(options.find(x=>x[0]===store.report)?.[1])}</h2><span class="subtle">${esc(start)} to ${esc(end)}</span></div>${reportGrid(data)}</div>${gst?'<p class="muted" style="font-size:11px;margin-top:15px">Preparation reports only. Review with your tax professional before filing.</p>':''}`;}
const renderReports=()=>renderReportPage(false);
const renderGst=()=>renderReportPage(true);
