  if(a==='settings-logo')return attachments('settings',store.boot.settings.id);
  if(a==='save-tax-rate'){const f=$('#tax-rate-form');if(!f.reportValidity())return;const d=formData(f);d.rate=Number(d.rate);await post('/api/tax-rates',d);await taxRates();return toast('Tax rate scheduled');}
