  if(a==='customer-ledger')return ledger('customer',id);
  if(a==='supplier-ledger')return ledger('supplier',id);
  if(a==='new-quotation')return quoteForm();
  if(a==='edit-quotation'){const quotes=rows(await api('/api/quotations'));return quoteForm(quotes.find(q=>String(q.id)===String(id)));}
  if(a==='approve-quotation'){await patch(`/api/quotations/${id}`,{status:'approved'});await view('quotations');return toast('Quotation approved');}
