  if(a==='convert-quotation')return openQuoteConvert(id);
  if(a==='submit-quote-convert')return submitQuoteConvert(id);
  if(a==='new-expense')return expenseForm();
  if(a==='save-expense'){const f=$('#expense-form');if(!f.reportValidity())return;const d=formData(f);d.amount=Number(d.amount);await post('/api/expenses',d);closeModal();await view('expenses');return toast('Expense recorded');}
