async function purchaseReturn(id){const purchase=await api('/api/purchases/'+id),items=purchase.items||[];if(!items.length)throw new Error('No returnable items found.');showModal('Purchase return',`<div class="info-banner alert-banner">Returned goods leave inventory and reduce the supplier balance.</div><form id="purchase-return-form" class="form-grid">${selectField('Product','purchase_item_id',items.map(x=>[x.id,(x.product_name||productById(x.product_id)?.name||x.product_id)+' · received '+qty(x.quantity)]),'','required')}${field('Quantity returned','quantity','number','1','min="0.001" step="0.000001" required')}<div class="field full"><label for="purchase-return-reason">Reason</label><textarea name="reason" id="purchase-return-reason" required></textarea></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn danger" data-action="submit-purchase-return" data-id="${esc(id)}">Post return</button>`);}
async function submitPurchaseReturn(id){const f=$('#purchase-return-form');if(!f.reportValidity())return;const d=formData(f);const note=await post(`/api/purchases/${id}/return`,{items:[{purchase_item_id:Number(d.purchase_item_id),quantity:Number(d.quantity)}],reason:d.reason});closeModal();await refreshBoot();await view('purchases');showModal('Purchase return posted',`<div class="info-banner">Debit note <strong>${esc(note.number)}</strong> was saved. Stock and supplier balance were updated.</div>`,`<button class="btn" data-action="close-modal">Done</button><a class="btn" href="/debit-notes/${esc(note.id)}/print" target="_blank" rel="noopener">Print</a><a class="btn primary" href="/debit-notes/${esc(note.id)}/pdf" target="_blank" rel="noopener">PDF</a>`);}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action],[data-view],[data-category],[data-pos-mode],[data-report],[data-purchase-tab],[data-sort-header]');if(!target)return;try{if(target.dataset.view){await view(target.dataset.view);return;}if(target.dataset.category){store.category=target.dataset.category;await renderPos();return;}if(target.dataset.posMode){store.posMode=target.dataset.posMode;await renderPos();return;}if(target.dataset.report){store.report=target.dataset.report;await renderReportPage(store.view==='gst');return;}if(target.dataset.purchaseTab){store.purchaseTab=target.dataset.purchaseTab;store.tablePage=0;store.sortHeader='';await renderPurchases();return;}if(target.dataset.sortHeader){store.sortDir=store.sortHeader===target.dataset.sortHeader?-store.sortDir:1;store.sortHeader=target.dataset.sortHeader;store.tablePage=0;await view(store.view);return;}if(target.dataset.action){e.preventDefault();await handleAction(target);}}catch(err){fail(err);}});
document.addEventListener('input',async e=>{const el=e.target;if(el.id==='pos-search'){store.productSearch=el.value;const pos=el.selectionStart;await renderPos();const next=$('#pos-search');next.focus();next.setSelectionRange(pos,pos);return;}if(el.id==='table-search'){store.tableSearch=el.value;const pos=el.selectionStart;const current=store.view;await view(current);const next=$('#table-search');if(next){next.focus();next.setSelectionRange(pos,pos);}return;}if(el.matches('[data-cart-field]')&&el.tagName!=='SELECT'){const row=store.cart[Number(el.dataset.index)];if(!row)return;row[el.dataset.cartField]=el.dataset.cartField==='unit'?el.value:Number(el.value);if(['quantity','unit_price'].includes(el.dataset.cartField)&&Number(row[el.dataset.cartField])<=0)return;persistCart();if(el.type!=='number')await renderPos();return;}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.matches('[data-cart-field]')){const row=store.cart[Number(el.dataset.index)];if(row){row[el.dataset.cartField]=el.dataset.cartField==='unit'?el.value:Number(el.value);if(el.dataset.cartField==='unit'){const p=productById(row.product_id);const conversion=(p?.conversions||[]).find(c=>(c.symbol||c.unit)===row.unit);row.unit_price=Number(p?.selling_price||0)*Number(conversion?.factor_to_base||1);}persistCart();await renderPos();}return;}if(el.id==='pos-customer'){store.customerId=el.value;persistCart();return;}if(el.id==='date-range'){store.reportRange=el.value;if(el.value==='custom'){$('#custom-range')?.classList.remove('hidden');return;}await view(store.view);return;}if(el.id==='range-start'||el.id==='range-end'){store.customStart=$('#range-start')?.value;store.customEnd=$('#range-end')?.value;if(store.customStart&&store.customEnd&&store.customStart<=store.customEnd)await view(store.view);return;}if(el.id==='f-place_of_supply_state'&&$('#payment-form')){const preview=await post('/api/sales/preview',{customer_id:store.customerId||null,place_of_supply_state:el.value,items:store.cart});store.preview=preview;const total=Number(preview.grand_total||0);$('#f-amount').value=total.toFixed(2);$('#split-amount-1').value=total.toFixed(2);$('#split-amount-2').value='';syncPaymentChoice($('#payment-form'),total);$('.info-banner').innerHTML=`${store.cart.length} items · Invoice total <strong>${money(total)}</strong> · GST ${money(preview.gst_total||0)}. This total is calculated by the server.`;return;}if(el.name==='method'&&(el.closest('#payment-form')||el.closest('#quote-convert-form'))){const form=el.closest('form');syncPaymentChoice(form,form.id==='payment-form'?Number(store.preview?.grand_total||0):Number(store.quoteTotal||0));return;}if(el.id==='f-line_product_id'){const p=productById(el.value);if(p)$('#f-line_price').value=store.modalKind==='purchase'||store.modalKind==='purchase-order'?p.purchase_price||0:p.selling_price||0;return;}}catch(err){fail(err);}});
document.addEventListener('submit',async e=>{if(e.target.id==='settings-form'){e.preventDefault();try{const d=formData(e.target);d.financial_year_start_month=Number(d.financial_year_start_month);for(const key of ['tax_inclusive','allow_negative_stock','is_gst_registered','e_invoice_applicable'])d[key]=d[key]==='true';await put('/api/settings',d);await refreshBoot();toast('Store settings saved');}catch(err){fail(err);}return;}if(e.target.id!=='login-form')e.preventDefault();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal-backdrop').classList.contains('hidden'))closeModal();if(e.key==='F2'){e.preventDefault();view('pos');}if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();view('pos').then(()=>$('#pos-search')?.focus());}});
$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal();});
$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#top-new-sale').addEventListener('click',()=>view('pos'));
(async()=>{try{$('#today').textContent=new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short',year:'numeric'});await refreshBoot();const saved=JSON.parse(localStorage.getItem(cartStorageKey())||'{}');store.cart=Array.isArray(saved.cart)?saved.cart.filter(x=>productById(x.product_id)):[];store.customerId=saved.customerId||'';store.checkoutKey=saved.checkoutKey||null;await view(store.boot.user?.role==='cashier'?'pos':'dashboard');}catch(err){fail(err);$('#content').innerHTML='<div class="card card-pad">Unable to load the store. Please refresh or sign in again.</div>';}})();
